<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Support/Cli.php';
try{$o=cliOptions();$config=Nutrition\Support\Database::configuration($o['private']);if(isset($o['init'])&&$config['driver']!=='mysql')throw new RuntimeException('MySQL configuration required');if($config['driver']==='sqlite'&&!is_file($o['private'].'/recipes.sqlite'))throw new RuntimeException('Existing SQLite database not found');$db=Nutrition\Support\Database::connect($o['private'],$config,!isset($o['init']));if(isset($o['init']))Nutrition\Support\Schema::apply($db);$out=['driver'=>$db->getAttribute(PDO::ATTR_DRIVER_NAME)];foreach(['users','dogs','recipes','dog_preferences','catalog_products','audit_events'] as $table)if(Nutrition\Support\Database::mysql($db)||in_array($table,['users','recipes'],true))$out[$table]=(int)$db->query('SELECT COUNT(*) FROM '.$table)->fetchColumn();echo json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;}catch(Throwable $e){fwrite(STDERR,'Storage check failed: '.$e->getMessage().PHP_EOL);exit(1);}
